package com.estoqueinteligente.report;
import com.estoqueinteligente.product.ProductResponse;
public class PurchaseSuggestionResponse{private final Long productId;private final String productName,categoryName,reason;private final Integer currentQuantity,minimumStock,suggestedQuantity;public PurchaseSuggestionResponse(ProductResponse p){productId=p.getId();productName=p.getName();categoryName=p.getCategoryName();currentQuantity=p.getQuantity();minimumStock=p.getMinimumStock();int difference=minimumStock-currentQuantity;suggestedQuantity=difference<=0?minimumStock:difference;reason=currentQuantity==0?"Produto zerado em estoque. Compra urgente recomendada.":"Produto abaixo do estoque mínimo. Reposição recomendada.";}public Long getProductId(){return productId;}public String getProductName(){return productName;}public String getCategoryName(){return categoryName;}public Integer getCurrentQuantity(){return currentQuantity;}public Integer getMinimumStock(){return minimumStock;}public Integer getSuggestedQuantity(){return suggestedQuantity;}public String getReason(){return reason;}}
